diff --git a/crates/opforge-asm/src/runtime_model.rs b/crates/opforge-asm/src/runtime_model.rs
index 5940387a..10e83b9d 100644
--- a/crates/opforge-asm/src/runtime_model.rs
+++ b/crates/opforge-asm/src/runtime_model.rs
@@ -48,6 +48,16 @@ pub(crate) fn build_execution_model_for_request_with_artifact_path(
     opasm_package_path: Option<&Path>,
     cwd_artifact_path: Option<&Path>,
 ) -> Option<HierarchyExecutionModel> {
+    // Explicit packages are authoritative; their loader never uses bundled fallback bytes.
+    if let Some(path) = opasm_package_path {
+        return runtime_bootstrap::bootstrap_execution_model_for_request(
+            Some(path),
+            cwd_artifact_path,
+            None,
+            false,
+        );
+    }
+
     #[cfg(any(feature = "vm-runtime-only", feature = "vm-runtime-opasm-unbundled"))]
     let _ = cpu;

diff --git a/crates/opforge-asm/src/tests.rs b/crates/opforge-asm/src/tests.rs
index 237c216d..89234d02 100644
--- a/crates/opforge-asm/src/tests.rs
+++ b/crates/opforge-asm/src/tests.rs
@@ -38460,6 +38460,33 @@ fn runtime_model_explicit_package_path_branch_matches_shared_bootstrap() {
     assert_runtime_model_supports_cpu(&shared_model, m6502_cpu_id);
 }

+#[test]
+fn runtime_model_invalid_explicit_package_never_uses_available_fallback() {
+    let registry = default_registry();
+    let directory = create_temp_dir("runtime-model-explicit-no-fallback");
+    let artifact_path = directory.join("valid.opasm");
+    let package_bytes =
+        build_hierarchy_package_from_registry(&registry).expect("build valid fallback");
+    fs::write(&artifact_path, &package_bytes).expect("write valid fallback");
+    assert!(crate::runtime_model::load_execution_model_from_path(&artifact_path).is_some());
+
+    let malformed = directory.join("malformed.opasm");
+    fs::write(&malformed, b"not an opasm package").expect("write malformed package");
+    for explicit in [directory.join("missing.opasm"), malformed] {
+        let model = crate::runtime_model::build_execution_model_for_request_with_artifact_path(
+            &registry,
+            m6502_cpu_id,
+            Some(&explicit),
+            Some(&artifact_path),
+        );
+        assert!(
+            model.is_none(),
+            "invalid explicit package must not fall back"
+        );
+        assert_eq!(fs::read(&artifact_path).unwrap(), package_bytes);
+    }
+}
+
